["t"]="nl",
},{
["s"]="uma TV EDUCATIVA na",
["t"]="text",
},{
["t"]="scroll",
},{
["s"]="MOCHILA.",
["t"]="text",
},{
["t"]="para",
},{
["s"]="Posso registrá-la para",
["t"]="text",
},{
["t"]="nl",
},{
["s"]="usar na hora, e vou",
["t"]="text",
},{
["t"]="scroll",
},{
["s"]="mostrar como!",
["t"]="text",
},{
["t"]="para",
},{
["s"]="Certo, vamos lá!",
["t"]="text",
},{
["t"]="para",
},{
["s"]="Não tire os olhos deste",
